import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import {
  grantAdminCredit,
  liftSuspension,
  lookupAdminUser,
} from '../src/generation/admin-client.ts';

function jsonFetch(body: unknown, status = 200): typeof fetch {
  return (async () =>
    new Response(JSON.stringify(body), { status })) as unknown as typeof fetch;
}

describe('lookupAdminUser', () => {
  it('sends the Clerk bearer token and the email as a query param', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const fetchImpl = (async (url: string, init?: RequestInit) => {
      calls.push([url, init]);
      return new Response(
        JSON.stringify({
          userId: 'user_1',
          spendableCreditMicroUsd: 5_000_000,
          grants: [],
        }),
        { status: 200 },
      );
    }) as unknown as typeof fetch;

    const result = await lookupAdminUser(
      'a@example.com',
      fetchImpl,
      async () => 'a-token',
    );

    assert.deepEqual(result, {
      ok: true,
      userId: 'user_1',
      spendableCreditMicroUsd: 5_000_000,
      grants: [],
      unreadable: 0,
    });
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/admin/user?email=a%40example.com');
    assert.equal(
      (init?.headers as Record<string, string>).Authorization,
      'Bearer a-token',
    );
  });

  it('surfaces the server error message', async () => {
    const result = await lookupAdminUser(
      'a@example.com',
      jsonFetch({ error: 'Not authorized.' }, 403),
    );
    assert.deepEqual(result, { ok: false, error: 'Not authorized.' });
  });

  it('treats a 200 with no readable userId as a failure, not a crash', async () => {
    const result = await lookupAdminUser('a@example.com', jsonFetch({}));
    assert.equal(result.ok, false);
  });
});

describe('grantAdminCredit', () => {
  it('sends the email, amount and note', async () => {
    const calls: Array<RequestInit | undefined> = [];
    const result = await grantAdminCredit(
      'a@example.com',
      500,
      'goodwill',
      (async (_url: string, init?: RequestInit) => {
        calls.push(init);
        return new Response(
          JSON.stringify({ userId: 'user_1', creditUsdCents: 500 }),
          { status: 200 },
        );
      }) as unknown as typeof fetch,
    );

    assert.deepEqual(result, {
      ok: true,
      userId: 'user_1',
      creditUsdCents: 500,
    });
    assert.equal(calls[0]?.method, 'POST');
    assert.deepEqual(JSON.parse(String(calls[0]?.body)), {
      email: 'a@example.com',
      amountUsdCents: 500,
      note: 'goodwill',
    });
  });

  it('surfaces the server error message rather than a generic one', async () => {
    const result = await grantAdminCredit(
      'a@example.com',
      500,
      null,
      jsonFetch({ error: 'No user found for a@example.com.' }, 404),
    );
    assert.deepEqual(result, {
      ok: false,
      error: 'No user found for a@example.com.',
    });
  });

  it('falls back to a generic message when the error body is unreadable', async () => {
    const result = await grantAdminCredit(
      'a@example.com',
      500,
      null,
      (async () =>
        new Response('not json', { status: 500 })) as unknown as typeof fetch,
    );
    assert.deepEqual(result, {
      ok: false,
      error: 'The admin request failed (500).',
    });
  });
});

describe('a grant row the page cannot read', () => {
  function serving(grants: unknown): typeof fetch {
    return (async () =>
      new Response(
        JSON.stringify({
          userId: 'user_1',
          spendableCreditMicroUsd: 5_000_000,
          grants,
        }),
        { status: 200 },
      )) as unknown as typeof fetch;
  }

  it('does not present a row with no amount or no actor as a grant', async () => {
    // The cast this replaces rendered these: "$NaN by undefined", which
    // reads as a broken page rather than a gap in the record, so the
    // natural response is to ignore it and grant again.
    const result = await lookupAdminUser(
      'a@example.com',
      serving([
        { grantedByEmail: 'admin@vibld.com', note: null },
        { creditUsdCents: 500, note: null },
        { creditUsdCents: 500, grantedByEmail: '  ', note: null },
        { creditUsdCents: Number.NaN, grantedByEmail: 'a@b.com', note: null },
        null,
        'a grant, honestly',
      ]),
      async () => null,
    );

    assert.ok(result.ok);
    assert.deepEqual(result.grants, []);
    assert.equal(result.unreadable, 6);
  });

  it('counts them rather than dropping them quietly', async () => {
    // A silently shorter history is the one failure this list must not
    // have: it is read to decide whether an earlier grant already landed,
    // and a missing row is how the same person gets paid twice.
    const result = await lookupAdminUser(
      'a@example.com',
      serving([
        {
          creditUsdCents: 500,
          grantedByEmail: 'admin@vibld.com',
          note: 'outage',
          createdAt: '2026-01-01T00:00:00Z',
        },
        { creditUsdCents: 900 },
      ]),
      async () => null,
    );

    assert.ok(result.ok);
    assert.equal(result.grants.length, 1);
    assert.equal(result.grants[0]?.grantedByEmail, 'admin@vibld.com');
    assert.equal(result.unreadable, 1);
  });

  it('refuses a lookup whose history it could not read at all', async () => {
    // Not an empty history. Defaulting to [] here would show "no past
    // grants" for an answer nobody could read, which is the silently
    // shortened list this change exists to prevent, at its worst: every row
    // missing and nothing said.
    for (const grants of [undefined, null, 'none', 42, { 0: 'a' }]) {
      const result = await lookupAdminUser(
        'a@example.com',
        serving(grants),
        async () => null,
      );
      assert.equal(result.ok, false, JSON.stringify(grants ?? null));
    }
  });

  it('is content with a history that is genuinely empty', async () => {
    // The other direction: a user with no grants is ordinary, and refusing
    // that lookup would break the common case.
    const result = await lookupAdminUser(
      'a@example.com',
      serving([]),
      async () => null,
    );
    assert.ok(result.ok);
    assert.deepEqual(result.grants, []);
    assert.equal(result.unreadable, 0);
  });

  it('keeps a readable grant that simply has no note', async () => {
    // The other direction: a note is genuinely optional, and refusing a row
    // for want of one would hide grants that are perfectly fine.
    const result = await lookupAdminUser(
      'a@example.com',
      serving([{ creditUsdCents: 500, grantedByEmail: 'admin@vibld.com' }]),
      async () => null,
    );

    assert.ok(result.ok);
    assert.equal(result.grants.length, 1);
    assert.equal(result.grants[0]?.note, null);
    assert.equal(result.unreadable, 0);
  });
});

describe('what a lookup says about refunds and disputes', () => {
  it('reads the suspension and every reversal it can, and drops one it cannot', async () => {
    const result = await lookupAdminUser(
      'a@example.com',
      jsonFetch({
        userId: 'user_1',
        spendableCreditMicroUsd: 0,
        grants: [],
        suspended: true,
        clawbacks: [
          {
            cause: 'refund',
            kind: 'topup',
            stripeChargeId: 'ch_1',
            reversedUsdCents: 2000,
            creditRemovedUsdCents: 800,
            creditShortfallUsdCents: 0,
            stripeSubscriptionId: null,
            suspends: false,
            liftedAt: null,
            createdAt: '2026-09-28T00:00:00Z',
          },
          { cause: 'refund', kind: 'something-else' },
        ],
      }),
      async () => null,
    );

    assert.equal(result.ok, true);
    if (!result.ok) return;
    assert.equal(result.suspended, true);
    assert.deepEqual(result.clawbacks, [
      {
        cause: 'refund',
        kind: 'topup',
        stripeChargeId: 'ch_1',
        reversedUsdCents: 2000,
        creditRemovedUsdCents: 800,
        creditShortfallUsdCents: 0,
        stripeSubscriptionId: null,
        suspends: false,
        liftedAt: null,
        createdAt: '2026-09-28T00:00:00Z',
      },
    ]);
  });
});

describe('liftSuspension', () => {
  it('posts the email with the bearer token and reads what was lifted', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const result = await liftSuspension(
      'a@example.com',
      (async (url: string, init?: RequestInit) => {
        calls.push([url, init]);
        return new Response(
          JSON.stringify({ ok: true, userId: 'user_1', lifted: 1 }),
          { status: 200 },
        );
      }) as unknown as typeof fetch,
      async () => 'a-token',
    );

    assert.deepEqual(result, { ok: true, userId: 'user_1', lifted: 1 });
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/admin/suspension/lift');
    assert.equal(init?.method, 'POST');
    assert.equal(init?.body, JSON.stringify({ email: 'a@example.com' }));
    assert.equal(
      (init?.headers as Record<string, string>).Authorization,
      'Bearer a-token',
    );
  });

  it('surfaces the server error message', async () => {
    const result = await liftSuspension(
      'a@example.com',
      jsonFetch({ error: 'Not authorized.' }, 403),
      async () => null,
    );
    assert.deepEqual(result, { ok: false, error: 'Not authorized.' });
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import {
  fetchMedia,
  formatBytes,
  removeMedia,
  uploadMedia,
} from '../src/generation/media-client.ts';

/**
 * The builder's calls to `/api/media`: what it sends, and what it makes of
 * every answer, including the ones that are not answers.
 */

const token = async () => 'tok';

function recorder(response: Response | Error) {
  const calls: { url: string; init: RequestInit }[] = [];
  const fetchImpl = (async (url: string, init: RequestInit = {}) => {
    calls.push({ url, init });
    if (response instanceof Error) throw response;
    return response;
  }) as unknown as typeof fetch;
  return { calls, fetchImpl };
}

describe('uploading a file', () => {
  it('sends the bytes raw, with the name and alt text encoded in headers', async () => {
    const { calls, fetchImpl } = recorder(
      Response.json(
        {
          media: {
            id: 'm1',
            path: 'media/hero.png',
            kind: 'image',
            contentType: 'image/png',
            bytes: 4,
            alt: 'Café at dawn',
          },
        },
        { status: 201 },
      ),
    );
    const file = new Blob([new Uint8Array([1, 2, 3, 4])], {
      type: 'image/png',
    });
    const result = await uploadMedia(
      file,
      { name: 'Café hero.png', alt: 'Café at dawn' },
      fetchImpl,
      token,
    );
    assert.equal(result.ok, true);
    const headers = calls[0]!.init.headers as Record<string, string>;
    assert.equal(calls[0]!.init.method, 'POST');
    assert.equal(headers.Authorization, 'Bearer tok');
    assert.equal(headers['content-type'], 'image/png');
    assert.equal(decodeURIComponent(headers['x-media-name']!), 'Café hero.png');
    assert.equal(decodeURIComponent(headers['x-media-alt']!), 'Café at dawn');
    assert.equal(headers['x-media-poster-for'], undefined);
    assert.equal(calls[0]!.init.body, file);
  });

  it("passes on the server's reason when it refuses", async () => {
    const { fetchImpl } = recorder(
      Response.json(
        { error: 'Only JPEG, PNG ... can be used.' },
        { status: 415 },
      ),
    );
    const result = await uploadMedia(
      new Blob(['<svg/>'], { type: 'image/svg+xml' }),
      { name: 'x.svg', alt: '' },
      fetchImpl,
      token,
    );
    assert.deepEqual(result, {
      ok: false,
      error: 'Only JPEG, PNG ... can be used.',
    });
  });

  it('says the upload never arrived when the network fails', async () => {
    const { fetchImpl } = recorder(new Error('offline'));
    const result = await uploadMedia(
      new Blob(['x']),
      { name: 'x', alt: '' },
      fetchImpl,
      token,
    );
    assert.equal(result.ok, false);
    if (!result.ok) assert.match(result.error, /did not reach Vibld/);
  });
});

describe('reading and pruning the library', () => {
  it('keeps only well-formed entries', async () => {
    const { fetchImpl } = recorder(
      Response.json({
        media: [
          { id: 'm1', path: 'media/a.png', kind: 'image', bytes: 1, alt: '' },
          { id: 'm2', path: 'media/b.svg', kind: 'script', bytes: 1, alt: '' },
        ],
        usage: { files: 1, bytes: 1, maxFiles: 30, maxBytes: 200 },
      }),
    );
    const library = await fetchMedia(fetchImpl, token);
    assert.equal(library?.media.length, 1);
    assert.equal(library?.usage.maxFiles, 30);
  });

  it('reads as unavailable rather than empty when it cannot be read', async () => {
    assert.equal(
      await fetchMedia(recorder(new Error('down')).fetchImpl, token),
      null,
    );
    assert.equal(
      await fetchMedia(
        recorder(new Response('nope', { status: 503 })).fetchImpl,
        token,
      ),
      null,
    );
  });

  it('removes by id, encoded', async () => {
    const { calls, fetchImpl } = recorder(Response.json({ removed: 'a b' }));
    assert.equal(await removeMedia('a b', fetchImpl, token), true);
    assert.equal(calls[0]!.url, '/api/media?id=a%20b');
    assert.equal(calls[0]!.init.method, 'DELETE');
  });

  it('writes sizes a person reads', () => {
    assert.equal(formatBytes(340 * 1024), '340 KB');
    assert.equal(formatBytes(1.25 * 1024 * 1024), '1.3 MB');
    assert.equal(formatBytes(10), '1 KB');
  });
});

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import {
  createPreviewShare,
  fetchPreviewShares,
  fetchPreviewStatus,
  revokePreviewShare,
  startSandboxPreview,
  stopSandboxPreview,
} from '../src/generation/preview-client.ts';

function jsonFetch(body: unknown, status = 200): typeof fetch {
  return (async () =>
    new Response(JSON.stringify(body), { status })) as unknown as typeof fetch;
}

describe('fetchPreviewStatus', () => {
  it('sends the Clerk bearer token and returns the parsed status', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const fetchImpl = (async (url: string, init?: RequestInit) => {
      calls.push([url, init]);
      return new Response(JSON.stringify({ status: 'installing' }), {
        status: 200,
      });
    }) as unknown as typeof fetch;

    const status = await fetchPreviewStatus(fetchImpl, async () => 'a-token');

    assert.deepEqual(status, { status: 'installing' });
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/preview');
    assert.equal(
      (init?.headers as Record<string, string>).Authorization,
      'Bearer a-token',
    );
  });

  it('omits the Authorization header when signed out', async () => {
    const calls: Array<RequestInit | undefined> = [];
    await fetchPreviewStatus(
      (async (_url: string, init?: RequestInit) => {
        calls.push(init);
        return new Response(JSON.stringify({ status: 'ready-to-start' }), {
          status: 200,
        });
      }) as unknown as typeof fetch,
      async () => null,
    );
    assert.equal(
      (calls[0]?.headers as Record<string, string>).Authorization,
      undefined,
    );
  });

  it('parses a queued status, including position', async () => {
    assert.deepEqual(
      await fetchPreviewStatus(jsonFetch({ status: 'queued', position: 3 })),
      { status: 'queued', position: 3 },
    );
  });

  it('parses a ready status', async () => {
    assert.deepEqual(
      await fetchPreviewStatus(
        jsonFetch({
          status: 'ready',
          url: 'https://5173-abc-def.vibld-preview.dev',
          expiresAt: 1_800_000_000_000,
        }),
      ),
      {
        status: 'ready',
        url: 'https://5173-abc-def.vibld-preview.dev',
        expiresAt: 1_800_000_000_000,
      },
    );
  });

  it('carries what tsc said about a project that does not compile', async () => {
    // internal issue 194: two of six real generations produced a project that fails
    // `npm run build`. The preview sandbox typechecks after installing,
    // and the finding rides along on the ready status rather than
    // becoming a failure -- the sandbox is up and the URL works.
    assert.deepEqual(
      await fetchPreviewStatus(
        jsonFetch({
          status: 'ready',
          url: 'https://5173-abc-def.vibld-preview.dev',
          expiresAt: 1_800_000_000_000,
          typecheckFailure:
            "src/App.tsx(3,10): error TS1484: 'ReactNode' is a type",
        }),
      ),
      {
        status: 'ready',
        url: 'https://5173-abc-def.vibld-preview.dev',
        expiresAt: 1_800_000_000_000,
        typecheckFailure:
          "src/App.tsx(3,10): error TS1484: 'ReactNode' is a type",
      },
    );
  });

  it('still reports a ready preview when the finding is unreadable', async () => {
    // The preview really is running. A finding this cannot read is dropped
    // rather than allowed to null the status, which would stop the poll
    // and take the Stop button away from a sandbox that is up.
    for (const typecheckFailure of [42, null, '', { message: 'no' }]) {
      const status = await fetchPreviewStatus(
        jsonFetch({
          status: 'ready',
          url: 'https://x.vibld-preview.dev',
          expiresAt: 1_800_000_000_000,
          typecheckFailure,
        }),
      );
      assert.equal(status?.status, 'ready', JSON.stringify(typecheckFailure));
      assert.equal(
        status?.status === 'ready' ? status.typecheckFailure : 'unset',
        undefined,
        JSON.stringify(typecheckFailure),
      );
    }
  });

  it('is null for an answer it cannot read, not a failed sandbox', async () => {
    // A failed status is the service saying the sandbox is not running, and
    // callers act on it: the poll stops asking, the panel takes the Stop
    // button away, and an unconfirmed stop treats it as settling whether
    // the sandbox survived. None of that follows from this client being
    // unable to parse a 200, so an unreadable answer is the same null a
    // dropped request produces and the poll keeps going.
    for (const body of [
      { status: 'ready' },
      { status: 'ready', url: 'https://x' },
      { status: 'nonsense' },
      {},
      { error: 'something' },
    ]) {
      assert.equal(
        await fetchPreviewStatus(jsonFetch(body)),
        null,
        JSON.stringify(body),
      );
    }
  });

  it('still reports a failure the service actually reported', async () => {
    assert.deepEqual(
      await fetchPreviewStatus(
        jsonFetch({ status: 'failed', error: 'No preview has been started.' }),
      ),
      { status: 'failed', error: 'No preview has been started.' },
    );
  });

  it('is null rather than throwing when signed out or unauthorized', async () => {
    assert.equal(
      await fetchPreviewStatus(jsonFetch({ error: 'Sign in required.' }, 401)),
      null,
    );
  });

  it('is null when the deployment has no preview endpoint at all', async () => {
    const failing = (async () => {
      throw new TypeError('Failed to fetch');
    }) as unknown as typeof fetch;
    assert.equal(await fetchPreviewStatus(failing), null);
  });
});

describe('startSandboxPreview', () => {
  it('posts the files and returns the parsed status', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const fetchImpl = (async (url: string, init?: RequestInit) => {
      calls.push([url, init]);
      return new Response(JSON.stringify({ status: 'installing' }), {
        status: 200,
      });
    }) as unknown as typeof fetch;

    const status = await startSandboxPreview(
      [{ path: 'src/App.tsx', content: 'x' }],
      fetchImpl,
      async () => 'a-token',
    );

    assert.deepEqual(status, { status: 'installing' });
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/preview');
    assert.equal(init?.method, 'POST');
    assert.deepEqual(JSON.parse(String(init?.body)), {
      files: [{ path: 'src/App.tsx', content: 'x' }],
    });
  });

  it('surfaces the server error message rather than failing opaquely', async () => {
    await assert.rejects(
      () =>
        startSandboxPreview(
          [],
          jsonFetch(
            { error: 'Preview is not configured for this deployment.' },
            503,
          ),
        ),
      /not configured for this deployment/,
    );
  });

  it('does not crash on an unreadable response body', async () => {
    const status = await startSandboxPreview(
      [],
      (async () =>
        new Response('not json', { status: 200 })) as unknown as typeof fetch,
    );
    assert.equal(status.status, 'failed');
  });
});

describe('stopSandboxPreview', () => {
  it('sends a DELETE request', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    await stopSandboxPreview(
      (async (url: string, init?: RequestInit) => {
        calls.push([url, init]);
        return new Response(JSON.stringify({ ok: true }), { status: 200 });
      }) as unknown as typeof fetch,
      async () => 'a-token',
    );
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/preview');
    assert.equal(init?.method, 'DELETE');
  });

  it('throws on a failed stop, rather than pretending it succeeded', async () => {
    await assert.rejects(
      () => stopSandboxPreview(jsonFetch({ error: 'nope' }, 500)),
      /nope/,
    );
  });
});

describe('fetchPreviewShares', () => {
  it('sends the Clerk bearer token and returns the parsed list', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const fetchImpl = (async (url: string, init?: RequestInit) => {
      calls.push([url, init]);
      return new Response(
        JSON.stringify({
          shares: [
            {
              shareId: 'share_1',
              createdAt: 1,
              expiresAt: 2,
              revoked: false,
              url: 'https://share.vibld-preview.dev/user_1/share_1?exp=2&sig=x',
            },
          ],
        }),
        { status: 200 },
      );
    }) as unknown as typeof fetch;

    const shares = await fetchPreviewShares(fetchImpl, async () => 'a-token');

    assert.equal(shares.length, 1);
    assert.equal(shares[0]!.shareId, 'share_1');
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/preview/share');
    assert.equal(
      (init?.headers as Record<string, string>).Authorization,
      'Bearer a-token',
    );
  });

  it('filters out anything not shaped like a share', async () => {
    const shares = await fetchPreviewShares(
      jsonFetch({ shares: [{ shareId: 'share_1' }, 'garbage', null] }),
    );
    assert.deepEqual(shares, []);
  });

  it('is an empty list rather than throwing when signed out or unauthorized', async () => {
    assert.deepEqual(
      await fetchPreviewShares(jsonFetch({ error: 'Sign in required.' }, 401)),
      [],
    );
  });

  it('is an empty list when the deployment has no preview endpoint at all', async () => {
    const failing = (async () => {
      throw new TypeError('Failed to fetch');
    }) as unknown as typeof fetch;
    assert.deepEqual(await fetchPreviewShares(failing), []);
  });
});

describe('createPreviewShare', () => {
  it('posts and returns the parsed grant', async () => {
    const calls: Array<[string, RequestInit | undefined]> = [];
    const fetchImpl = (async (url: string, init?: RequestInit) => {
      calls.push([url, init]);
      return new Response(
        JSON.stringify({
          shareId: 'share_1',
          expiresAt: 1_800_000_000_000,
          url: 'https://share.vibld-preview.dev/user_1/share_1?exp=1&sig=x',
        }),
        { status: 200 },
      );
    }) as unknown as typeof fetch;

    const share = await createPreviewShare(fetchImpl, async () => 'a-token');

    assert.equal(share.shareId, 'share_1');
    assert.equal(share.revoked, false);
    assert.equal(
      share.url,
      'https://share.vibld-preview.dev/user_1/share_1?exp=1&sig=x',
    );
    const [url, init] = calls[0]!;
    assert.equal(url, '/api/preview/share');
    assert.equal(init?.method, 'POST');
  });

  it('surfaces the server error message rather than failing opaquely', async () => {
    await assert.rejects(
      () =>
        createPreviewShare(
          jsonFetch({ error: 'This preview is not currently running.' }, 409),
        ),
      /not currently running/,
    );
  });

