import {
  type AnalyticsDataset,
  type Attribution,
  attributionFrom,
  pathOf,
  record,
} from './analytics.ts';
import { secured } from '@vibld/security-headers';
import {
  apiCatalogResponse,
  API_CATALOG_PATH,
  authorizationMetadata,
  isAuthorizationMetadataPath,
  withHomeLinks,
} from './agent-discovery.ts';
import { markdownFor, varyByAccept } from './markdown.ts';
import {
  handleRoadmapVote,
  handleRoadmapVotes,
  methodNotAllowed,
} from './roadmap-api.ts';
import { type RoadmapD1Database, sweep } from './roadmap-store.ts';

export interface Env {
  /**
   * Worker secret, pairs with the public site key the roadmap's vote widget
   * uses (docs/decisions.md L29); checked by worker/roadmap-api.ts through
   * worker/turnstile.ts. Unset means a vote from a browser the Worker does
   * not know yet is refused with a 503, not let through.
   */
  TURNSTILE_SECRET_KEY?: string;
  /** Workers Analytics Engine dataset. Absent in local dev; see worker/analytics.ts. */
  ANALYTICS?: AnalyticsDataset;
  /**
   * The prerendered build, bound by wrangler.jsonc's `assets`.
   *
   * Production used to serve pages from these assets without invoking this
   * Worker at all (`run_worker_first: ["/api/*"]`). That is no longer true,
   * and the reason is `canonicalHost` below: a redirect can only be issued
   * by something the request reaches, and a page request never reached here.
   *
   * Typed by the one method this file calls rather than as `Fetcher`, which
   * would mean pulling the Workers type package into an app that otherwise
   * needs none of it.
   */
  ASSETS?: { fetch(request: Request): Promise<Response> };
  /**
   * Set to "1" on preview deployments only (wrangler.preview.jsonc).
   *
   * A preview of this site is a byte-for-byte copy of vibld.com on a public
   * hostname. Left indexable it competes with the real site for the name,
   * which is the exact problem the marketing work is trying to solve, so a
   * copy that can outrank the original is worse than having no preview.
   */
  VIBLD_NOINDEX?: string;
  /**
   * The roadmap's votes (worker/roadmap-api.ts), bound by wrangler.jsonc.
   * Deliberately absent on the preview deployment, where /api/roadmap/*
   * answers 503: a vote cast while reviewing a change is not a vote.
   */
  ROADMAP_DB?: RoadmapD1Database;
}

/**
 * Every request arrives here now (`run_worker_first: true`), not only
 * `/api/*`, and the site's own pages are served from the `ASSETS` binding at
 * the bottom of this handler.
 *
 * That changed to make one hostname canonical. `_redirects`, the mechanism
 * built for exactly this, cannot do it: Cloudflare documents domain-level
 * redirects as unsupported there, and says in as many words that its rules
 * are not applied to requests a Worker serves. A second Worker bound to
 * `www.vibld.com` alone would have kept the apex free of invocations, but a
 * custom domain belongs to one Worker at a time, so moving it is a step
 * nothing in CI can take unattended, and a marketing site that is down
 * because a deploy needed a human is worse than one that costs a Worker
 * invocation per request.
 *
 * So that is the trade, stated rather than buried: every asset request on
 * this site now runs this script. At this site's size that is a rounding
 * error against the Workers Paid request allowance, and the thing bought
 * with it is that `vibld.com` is the only hostname that ever answers 200.
 */
export default {
  /**
   * One exit, so a route added later cannot forget the headers.
   *
   * `secured` is applied here rather than at each `return` below for the
   * reason this site had no security headers at all: they were nobody's
   * job at any particular return statement. A `_headers` file cannot help
   * here, because Cloudflare never applies one to a response a Worker
   * generated and this Worker generates every response on the site
   * (`run_worker_first: true`, for the www redirect).
   */
  async fetch(request: Request, env: Env): Promise<Response> {
    return secured(await route(request, env));
  },

  /**
   * wrangler.jsonc's cron: deletes rate-limit rows whose window has closed
   * and salts from earlier days, so a hashed address is not kept longer than
   * the window it was counted in when nobody votes to trigger the same
   * cleanup (worker/roadmap-store.ts).
   */
  async scheduled(_controller: unknown, env: Env): Promise<void> {
    if (env.ROADMAP_DB) await sweep(env.ROADMAP_DB, Date.now());
  },
};

async function route(request: Request, env: Env): Promise<Response> {
  const url = new URL(request.url);

  // First, before any route or asset. A redirect that runs after the thing
  // it is redirecting away from has already answered is not a redirect.
  const canonical = canonicalHost(url);
  if (canonical) {
    return new Response(null, {
      // A 301 turns a POST into a GET in most clients, which for
      // `/api/roadmap/vote` or `/api/hit` would silently discard the body.
      // 308 is the same permanent redirect with the method and body
      // preserved, so the two are split by method rather than one being
      // chosen for both.
      // GET and HEAD keep 301 because it is the status every crawler and
      // link checker already understands.
      status: request.method === 'GET' || request.method === 'HEAD' ? 301 : 308,
      headers: { location: canonical },
    });
  }

  // The builder API's catalog (worker/agent-discovery.ts, D186).
  if (url.pathname === API_CATALOG_PATH) {
    return apiCatalogResponse(request);
  }
  // Clerk's sign-in metadata, redirected to its own origin (D180).
  if (isAuthorizationMetadataPath(url.pathname)) {
    return authorizationMetadata(request);
  }

  if (url.pathname === '/api/hit' && request.method === 'POST') {
    return handleHit(request, env);
  }
  if (url.pathname === '/api/roadmap/votes') {
    return request.method === 'GET'
      ? handleRoadmapVotes(request, env)
      : methodNotAllowed('GET');
  }
  if (url.pathname === '/api/roadmap/vote') {
    return request.method === 'POST'
      ? handleRoadmapVote(request, env)
      : methodNotAllowed('POST');
  }

  // Every other `/api/` path, before the asset store sees it: Static Assets
  // answers a POST with 405, so a retired write endpoint such as
  // `/api/waitlist` (D168) would otherwise read as "wrong method" rather
  // than "not here".
  if (url.pathname.startsWith('/api/')) {
    return new Response('Not found', { status: 404 });
  }

  // Last, so an `/api/` route is never served as a page. `VIBLD_NOINDEX` is
  // set on the preview deployment only, and keeps a byte-for-byte copy of
  // this site out of the index; production serves the same bytes without
  // that header.
  if (env.ASSETS) {
    // An agent that asks for Markdown gets the page as Markdown (see
    // worker/markdown.ts); everyone else gets the HTML, marked as varying by
    // the same header.
    const markdown = await markdownFor(request, env.ASSETS);
    if (markdown) {
      const linked = withHomeLinks(url.pathname, markdown);
      return env.VIBLD_NOINDEX === '1' ? noindex(linked) : linked;
    }
    // The home page also points at the builder API (worker/agent-discovery.ts).
    const response = withHomeLinks(
      url.pathname,
      varyByAccept(
        permanentRedirect(
          request.method,
          hashedAssetHeaders(
            url.pathname,
            discoveryHeaders(
              url.pathname,
              fontHeaders(url.pathname, await env.ASSETS.fetch(request)),
            ),
          ),
        ),
      ),
    );
    return env.VIBLD_NOINDEX === '1' || isLayerDemo(url.pathname)
      ? noindex(response)
      : response;
  }
  return new Response('Not found', { status: 404 });
}

/**
 * A layer's reference page (app/layers.ts, D101): a demonstration of a
 * made-up product, served as it is, so it says nothing about vibld and is
 * kept out of search results. Its page on /templates is indexed as usual.
 */
export function isLayerDemo(pathname: string): boolean {
  return pathname === '/layers' || pathname.startsWith('/layers/');
}

/**
 * Where this request should have gone, or null when it is already there.
 *
 * Only a leading `www.` is stripped, and only that: this Worker answers on
 * `vibld.com`, on `www.vibld.com`, and on a `workers.dev` preview hostname,
 * and the preview must keep serving itself rather than redirecting reviewers
 * to production.
 *
 * The path and query survive, so a shared `www` link to a legal page or a
 * campaign URL lands on the same page with its UTM parameters intact rather
 * than on the home page. The fragment is not handled because it is never
 * sent: the browser reattaches it to whatever this points at.
 */
export function canonicalHost(url: URL): string | null {
  if (!url.hostname.startsWith('www.')) return null;
  const canonical = new URL(url.toString());
  canonical.hostname = url.hostname.slice('www.'.length);
  return canonical.toString();
}

/**
 * The self-hosted fonts, cached for a year and typed as fonts.
 *
 * The asset store's default is to revalidate every file on every use, which
 * is right for pages and wrong for these: every page preloads two of them,
 * and they never change at a given URL, because each filename carries the
 * Fontsource version it was copied from (app.css). A new version is a new
 * file, so `immutable` cannot pin a reader to a stale one.
 *
 * The content type is set here rather than trusted, because a preload with
 * `type="font/woff2"` is ignored by a browser that is sent anything else.
 * Only a successful response is touched: a 404 for a missing font must not
 * be cached for a year.
 */
export function fontHeaders(pathname: string, response: Response): Response {
  if (!/^\/fonts\/[^/]+\.woff2$/.test(pathname) || response.status !== 200) {
    return response;
  }
  const headers = new Headers(response.headers);
  headers.set('content-type', 'font/woff2');
  headers.set('cache-control', 'public, max-age=31536000, immutable');
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * The MCP Server Card (D182), readable from any origin: SEP-1649 asks for
 * these headers so a browser-based client elsewhere can discover `/mcp`.
 */
export function discoveryHeaders(
  pathname: string,
  response: Response,
): Response {
  if (pathname !== '/.well-known/mcp/server-card.json') return response;
  const headers = new Headers(response.headers);
  headers.set('access-control-allow-origin', '*');
  headers.set('access-control-allow-methods', 'GET');
  headers.set('access-control-allow-headers', 'Content-Type');
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * The build's own scripts and stylesheets, cached for a year.
 *
 * Vite names every file it writes to `/assets/` after a hash of its
 * contents, so a file at a given URL never changes: a new build is a new
 * name, and the page that asks for it is revalidated on every visit. The
 * asset store's default (`max-age=0, must-revalidate`) made every page view
 * ask again for roughly 300 KB of JavaScript that could not have changed.
 *
 * Only a name that carries a hash is touched, and only a 200, for the same
 * reason as `fontHeaders`: a missing file must not be cached for a year.
 */
export function hashedAssetHeaders(
  pathname: string,
  response: Response,
): Response {
  if (
    !/^\/assets\/[^/]+-[A-Za-z0-9_-]{8}\.(?:js|css)$/.test(pathname) ||
    response.status !== 200
  ) {
    return response;
  }
  const headers = new Headers(response.headers);
  headers.set('cache-control', 'public, max-age=31536000, immutable');
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * The asset store's own redirects, made permanent.
 *
 * `html_handling: "drop-trailing-slash"` answers `/pricing/`,
 * `/pricing/index.html` and `/index.html` with a 307 to the canonical form.
 * A 307 says "temporary", so a crawler keeps the old URL on file and comes
 * back to it; the move is not temporary, and a 301 is the status that says
 * so. Only GET and HEAD, for the reason `canonicalHost`'s caller gives: a
 * 301 turns a POST into a GET.
 */
export function permanentRedirect(
  method: string,
  response: Response,
): Response {
  if (response.status !== 307 || (method !== 'GET' && method !== 'HEAD')) {
    return response;
  }
  return new Response(null, { status: 301, headers: response.headers });
}

/**
 * The same response, told not to be indexed.
 *
 * Rebuilt rather than mutated: an immutable `Headers` on a response from a
 * binding throws on `set`, and a preview that 500s is not a preview.
 */
function noindex(response: Response): Response {
  const headers = new Headers(response.headers);
  headers.set('x-robots-tag', 'noindex, nofollow');
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * Resolves the attribution the caller reported. The page beacon sends the
 * page's own URL and referrer, because the Worker sees only its own `/api/*`
 * URL -- not the page the visitor was actually on.
 *
 * Two candidates, in order, and the same rule applied to both: it counts only
 * if it names a page on this site.
 *
 * The rule is one function rather than a check at each branch because the
 * first version of this checked only the `Referer` fallback and trusted
 * whatever `page_url` a caller sent. `/api/hit` takes unauthenticated posts,
 * so that was an open door: anyone could write `/their/page` and
 * `utm_campaign=whatever` straight into this site's traffic report.
 * Per-branch checks are how the second branch gets forgotten.
 *
 * The last resort is deliberately not `request.url`. When `page_url` is
 * empty, falling back to the Worker's own URL would file the event under an
 * `/api/` path nobody visited, splitting the real page's numbers rather than
 * merely rounding them. A browser sends `Referer` with a same-origin post as
 * the full URL, so the query string and its UTM parameters survive with it.
 *
 * What this does not claim: a caller can still send a plausible same-host URL
 * and be believed. Every field here is reported by the client and none of it
 * can be proved. The check removes the ability to write arbitrary paths and
 * campaigns from anywhere, which is worth having; it does not make an
 * unauthenticated beacon trustworthy, and nothing short of not having one
 * would.
 */
function attributionOf(
  request: Request,
  pageUrl: string,
  pageReferrer: string,
): { attribution: Attribution; path: string } {
  const selfHost = new URL(request.url).hostname;
  const url =
    onThisSite(pageUrl, selfHost) ??
    onThisSite(request.headers.get('referer'), selfHost) ??
    '';
  return {
    attribution: attributionFrom(url, pageReferrer, selfHost),
    // With nothing believable to go on, "/" is an honest guess at where a
    // visitor was. `pathOf` answers "/" for a value it cannot parse.
    path: pathOf(url),
  };
}

/** A URL, but only when it names a page on this site. */
function onThisSite(
  candidate: string | null | undefined,
  selfHost: string,
): string | null {
  if (!candidate) return null;
  try {
    return new URL(candidate).hostname === selfHost ? candidate : null;
  } catch {
    // Relative, malformed, or not a URL at all. All the same answer: this is
    // not something to record a path from.
    return null;
  }
}

/**
 * The pageview beacon. Answers 204 unconditionally and as early as possible:
 * the caller is a fire-and-forget `sendBeacon` that ignores the response, and
 * a failed measurement must never surface to a visitor.
 */
async function handleHit(request: Request, env: Env): Promise<Response> {
  try {
    const form = await request.formData();
    const { attribution, path } = attributionOf(
      request,
      String(form.get('page_url') ?? ''),
      String(form.get('page_referrer') ?? ''),
    );
    record(env.ANALYTICS, 'pageview', request, attribution, path);
  } catch (error) {
    console.error('hit failed', error);
  }
  return new Response(null, { status: 204 });
}

/**
 * The two roadmap endpoints, as worker/index.ts routes them:
 *
 *   GET  /api/roadmap/votes  the counts, and what this browser voted for
 *   POST /api/roadmap/vote   `{ id, turnstile? }`, toggles this browser's vote
 *
 * Every decision is a pure function in roadmap.ts and every read and write is
 * in roadmap-store.ts; this file is the order they happen in. That order is
 * the part worth reading:
 *
 *   1. the request is shaped right and names a votable item (no database);
 *   2. the address has votes left in this window, counted before anything
 *      else touches the database or Cloudflare, so a script is refused before
 *      it can make either do work;
 *   3. a browser the Worker does not know passes Turnstile, and is given a
 *      new voter id in the same transaction as its first vote;
 *   4. the vote is toggled, and the state read back is what is returned.
 */

import {
  NO_STORE,
  ROADMAP_TURNSTILE_ACTION,
  type Refusal,
  checkRefusal,
  clientIp,
  countsFor,
  ipHash,
  itemRefusal,
  newVoterId,
  originRefusal,
  parseVoteRequest,
  rateRefusal,
  voterCookie,
  voterHash,
  voterIdFrom,
  votedFor,
} from './roadmap.ts';
import {
  type RoadmapD1Database,
  countHit,
  isKnownVoter,
  readBoard,
  toggleVote,
  todaysSalt,
} from './roadmap-store.ts';
import { isTurnstileVerified, turnstileVerifyRequest } from './turnstile.ts';

export interface RoadmapEnv {
  /**
   * wrangler.jsonc's `vibld-marketing-roadmap`. Absent on the preview
   * deployment on purpose (wrangler.preview.jsonc), where both endpoints
   * answer 503 and the page shows its items without counts.
   */
  ROADMAP_DB?: RoadmapD1Database;
  /** The site's Turnstile secret (worker/turnstile.ts): one site key, one secret. */
  TURNSTILE_SECRET_KEY?: string;
}

function json(
  body: Record<string, unknown>,
  status: number,
  extra: Record<string, string> = {},
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...NO_STORE, ...extra },
  });
}

function refuse(refusal: Refusal, extra: Record<string, string> = {}) {
  return json({ error: refusal.error }, refusal.status, extra);
}

const UNAVAILABLE: Refusal = { status: 503, error: 'unavailable' };

export async function handleRoadmapVotes(
  request: Request,
  env: RoadmapEnv,
): Promise<Response> {
  if (!env.ROADMAP_DB) return refuse(UNAVAILABLE);
  try {
    const id = voterIdFrom(request);
    const board = await readBoard(
      env.ROADMAP_DB,
      id === null ? null : await voterHash(id),
    );
    return json(
      {
        counts: countsFor(board.countRows),
        voted: board.known ? votedFor(board.votedRows) : [],
        // Whether this browser's next vote needs a Turnstile token. The
        // cookie is HttpOnly, so the page cannot find out any other way.
        verified: board.known,
      },
      200,
    );
  } catch (error) {
    console.error('roadmap: reading votes failed', error);
    return refuse(UNAVAILABLE);
  }
}

export async function handleRoadmapVote(
  request: Request,
  env: RoadmapEnv,
  nowMs: number = Date.now(),
): Promise<Response> {
  const origin = originRefusal(request);
  if (origin) return refuse(origin);
  const parsed = await parseVoteRequest(request);
  if (!parsed.ok) return refuse(parsed);
  const item = itemRefusal(parsed.body.id);
  if (item) return refuse(item);

  const db = env.ROADMAP_DB;
  if (!db) return refuse(UNAVAILABLE);

  try {
    const hits = await countHit(
      db,
      await ipHash(clientIp(request), await todaysSalt(db, nowMs)),
      nowMs,
    );
    const limited = rateRefusal(hits, nowMs);
    if (limited) {
      return refuse(limited, { 'retry-after': String(limited.retryAfter) });
    }

    const presented = voterIdFrom(request);
    const known =
      presented !== null &&
      (await isKnownVoter(db, await voterHash(presented)));

    let voterId: string;
    if (known) {
      voterId = presented!;
    } else {
      const needs = checkRefusal({
        token: [REDACTED],
        secretConfigured: Boolean(env.TURNSTILE_SECRET_KEY),
      });
      if (needs) return refuse(needs);
      const verdict = await verifyTurnstile(
        parsed.body.turnstile,
        env.TURNSTILE_SECRET_KEY!,
        request,
      );
      if (verdict) return refuse(verdict);
      // Always a new id, never the one the request presented: a voter id is
      // one this Worker made, so a client cannot choose the value it will be
      // known by.
      voterId = newVoterId();
    }

    const result = await toggleVote(db, {
      voter: await voterHash(voterId),
      itemId: parsed.body.id,
      nowMs,
      register: !known,
    });
    return json({ id: parsed.body.id, ...result }, 200, {
      // Set again on every vote, so the cookie's lifetime runs from the last
      // time this browser voted rather than the first.
      'set-cookie': voterCookie(voterId),
    });
  } catch (error) {
    console.error('roadmap: vote failed', error);
    return refuse(UNAVAILABLE);
  }
}

/**
 * Null when the token passed. A refusal otherwise, and a different one for
 * "Cloudflare could not be asked" than for "Cloudflare said no": the first is
 * ours to fix, and telling a person their check failed when it never ran
 * would send them round the same loop for nothing.
 */
async function verifyTurnstile(
  token: string,
  secret: string,
  request: Request,
): Promise<Refusal | null> {
  const { url, init } = turnstileVerifyRequest(
    token,
    secret,
    request.headers.get('cf-connecting-ip') ?? undefined,
  );
  try {
    const response = await fetch(url, init);
    if (!response.ok) return { status: 503, error: 'check-unavailable' };
    return isTurnstileVerified(await response.json(), ROADMAP_TURNSTILE_ACTION)
      ? null
      : { status: 403, error: 'check-failed' };
  } catch (error) {
    console.error('roadmap: Turnstile verification request threw', error);
    return { status: 503, error: 'check-unavailable' };
  }
}

/** For the routes' other methods: said, rather than a 404 that implies no route. */
export function methodNotAllowed(allow: string): Response {
  return new Response(null, {
    status: 405,
    headers: { allow, 'cache-control': 'no-store' },
  });
}

import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';

import {
  describedBy,
  handleHealth,
  handleOpenApi,
} from '../worker/api-description.ts';
import { OPENAPI, UNDESCRIBED } from '../worker/openapi.ts';

/*
 * The description is written by hand, so these hold it to the router: a
 * route added without a description, or a description left behind by a
 * route that was removed, fails here rather than reaching an agent.
 */

const WORKER = fileURLToPath(new URL('../worker/', import.meta.url));

async function routedPaths(): Promise<string[]> {
  const source = await readFile(join(WORKER, 'index.ts'), 'utf8');
  return [
    ...new Set(
      [...source.matchAll(/pathname === '(\/api\/[^']+)'/g)].map(
        (match) => match[1]!,
      ),
    ),
  ];
}

/** `/api/projects/:id` as OpenAPI writes it, `/api/projects/{id}`. */
function templated(path: string): string {
  return path.replace(/:([a-z]+)/g, '{$1}');
}

const HOSTED_ORIGIN = 'https://app.vibld.com';

/** A deployment signed in with Clerk, as app.vibld.com is. */
const CLERK = { CLERK_FRONTEND_API_URL: 'https://clerk.vibld.com' };

/** Every 401 description in a served document. */
function unauthorized(document: {
  paths: Record<string, Record<string, unknown>>;
}): string[] {
  const found: string[] = [];
  for (const item of Object.values(document.paths)) {
    for (const operation of Object.values(item)) {
      const responses = (operation as { responses?: Record<string, unknown> })
        .responses;
      const refused = responses?.['401'] as
        { description?: string } | undefined;
      if (refused?.description) found.push(refused.description);
    }
  }
  return found;
}

const METHODS = ['get', 'put', 'post', 'delete', 'patch', 'head', 'options'];

describe('the OpenAPI description', () => {
  it('describes every route the router has, apart from administration and deliveries', async () => {
    const routed = await routedPaths();
    assert.ok(routed.length > 40, `only found ${routed.length} routes`);
    const missing = routed.filter(
      (path) =>
        !path.startsWith('/api/admin/') &&
        !(path in UNDESCRIBED) &&
        !(templated(path) in OPENAPI.paths),
    );
    assert.deepEqual(missing, [], `undescribed: ${missing.join(', ')}`);
  });

  it('describes no route the router does not have', async () => {
    const routed = new Set((await routedPaths()).map(templated));
    const stale = Object.keys(OPENAPI.paths).filter(
      (path) => !routed.has(path),
    );
    assert.deepEqual(stale, [], `not routed: ${stale.join(', ')}`);
  });

  it('describes nothing it leaves out, and leaves out only what is routed', async () => {
    const routed = new Set(await routedPaths());
    for (const path of Object.keys(UNDESCRIBED)) {
      assert.ok(routed.has(path), `${path} is not routed`);
      assert.ok(!(path in OPENAPI.paths), `${path} is both`);
    }
    assert.ok(
      !Object.keys(OPENAPI.paths).some((path) =>
        path.startsWith('/api/admin/'),
      ),
    );
  });

  it('gives every operation an id, a summary, a tag and its responses', () => {
    const ids = new Set<string>();
    const tags = new Set(OPENAPI.tags.map((tag) => tag.name));
    for (const [path, item] of Object.entries(OPENAPI.paths)) {
      for (const method of METHODS) {
        const op = (item as Record<string, Record<string, unknown>>)[method];
        if (!op) continue;
        const where = `${method.toUpperCase()} ${path}`;
        assert.equal(typeof op.operationId, 'string', where);
        assert.ok(!ids.has(op.operationId as string), `${where}: duplicate id`);
        ids.add(op.operationId as string);
        assert.equal(typeof op.summary, 'string', where);
        for (const tag of op.tags as string[]) {
          assert.ok(tags.has(tag), `${where}: unknown tag ${tag}`);
        }
        assert.ok(
          Object.keys(op.responses as object).length > 0,
          `${where}: no responses`,
        );
      }
    }
    assert.ok(ids.size > 50, `only ${ids.size} operations`);
  });

  it('resolves every reference to a schema it defines', () => {
    const text = JSON.stringify(OPENAPI);
    const refs = new Set(
      [...text.matchAll(/"\$ref":"#\/components\/schemas\/([^"]+)"/g)].map(
        (match) => match[1]!,
      ),
    );
    const defined = OPENAPI.components.schemas as Record<string, unknown>;
    const broken = [...refs].filter((name) => !(name in defined));
    assert.deepEqual(broken, []);
  });

  it('requires a JSON body wherever the Worker refuses a write without one', () => {
    // project-handlers.ts runs writeGuard on every POST and PATCH, and
    // share-handlers.ts checks the origin on every POST: both answer 415
    // unless the request says it carries JSON. A generated client sends that
    // header only for a body the description says is required.
    const paths = OPENAPI.paths as Record<
      string,
      Record<string, { requestBody?: Record<string, unknown> }>
    >;
    const loose: string[] = [];
    for (const [path, item] of Object.entries(paths)) {
      if (!/^\/api\/(projects|share)\//.test(path)) continue;
      for (const method of ['post', 'patch']) {
        const operation = item[method];
        if (!operation) continue;
        const body = operation.requestBody as
          { required?: boolean; content?: Record<string, unknown> } | undefined;
        if (body?.required !== true || !body.content?.['application/json']) {
          loose.push(`${method.toUpperCase()} ${path}`);
        }
      }
    }
    assert.deepEqual(loose, []);
  });

  it('asks the owner session writes for the Origin owner-auth.ts checks', () => {
    // sameOrigin refuses a POST or DELETE with no Origin header, so a
    // client generated without one could never sign in or out.
    const owner = (OPENAPI.paths as Record<string, Record<string, unknown>>)[
      '/api/owner/session'
    ]!;
    for (const method of ['post', 'delete']) {
      const { parameters } = owner[method] as {
        parameters: { name: string; in: string; required?: boolean }[];
      };
      assert.ok(
        parameters.some(
          (p) => p.name === 'Origin' && p.in === 'header' && p.required,
        ),
        method,
      );
    }
  });

  it('never offers the generic Error as one of exactly one choice', () => {
    // A specialized error extends Error, so a response matching it matches
    // Error too, and a oneOf with both rejects every such response.
    const overlapping: string[] = [];
    const visit = (value: unknown, at: string): void => {
      if (Array.isArray(value)) {
        value.forEach((v, i) => visit(v, `${at}/${i}`));
        return;
      }
      if (value === null || typeof value !== 'object') return;
      for (const [key, v] of Object.entries(value)) {
        if (
          key === 'oneOf' &&
          JSON.stringify(v).includes('"#/components/schemas/Error"')
        ) {
          overlapping.push(at);
        }
        visit(v, `${at}/${key}`);
      }
    };
    visit(OPENAPI.paths, '');
    assert.deepEqual(overlapping, []);
  });

  it('describes every field a preview status can carry', () => {
    const schemas = OPENAPI.components.schemas as Record<
      string,
      { properties?: Record<string, unknown> }
    >;
    assert.ok(schemas.PreviewStatus!.properties!.updatingTo);
  });

  it('carries no payment extension', () => {
    // D183: agent commerce is skipped, so nothing here asks to be paid.
    assert.doesNotMatch(JSON.stringify(OPENAPI), /x-payment/i);
  });
});

describe('the routes that describe the API', () => {
  it('serve the document to any origin', async () => {
    const response = handleOpenApi(
      new Request('https://app.vibld.com/api/openapi.json'),
      CLERK,
    );
    assert.equal(response.status, 200);
    assert.equal(
      response.headers.get('content-type'),
      'application/vnd.oai.openapi+json; charset=utf-8',
    );
    assert.equal(response.headers.get('access-control-allow-origin'), '*');
    assert.deepEqual(await response.json(), OPENAPI);
  });

  it('never advertises the scheme a proxy forwarded over', () => {
    // Traefik on the VPS terminates TLS and forwards over http.
    const document = describedBy('http://builder.example.com', 'owner');
    assert.doesNotMatch(JSON.stringify(document.servers), /http:/);
  });

  it('names the deployment that served it as the server', async () => {
    // A client generated from a self-hosted copy must not call the hosted
    // builder, least of all with that copy's owner password.
    const response = handleOpenApi(
      new Request('https://builder.example.com/api/openapi.json'),
      CLERK,
    );
    const document = (await response.json()) as typeof OPENAPI;
    assert.deepEqual(document.servers, [
      { url: '/', description: 'This deployment' },
    ]);
    assert.deepEqual(
      document,
      describedBy('https://builder.example.com', 'clerk'),
    );
  });

  it('asks for the sign-in the deployment accepts', async () => {
    const response = handleOpenApi(
      new Request('https://builder.example.com/api/openapi.json'),
      {
        VIBLD_AUTH: 'access',
        VIBLD_ACCESS_TEAM_DOMAIN: 'team.cloudflareaccess.com',
        VIBLD_ACCESS_AUD: 'aud',
      },
    );
    const text = await response.text();
    assert.doesNotMatch(text, /"clerk"/);
    // Only the hosted builder's own sentence still names Clerk's header,
    // and no refusal blames a missing bearer token.
    assert.equal(text.match(/Authorization: [REDACTED], 1);
    for (const description of unauthorized(JSON.parse(text))) {
      assert.doesNotMatch(description, /bearer|authorization/i);
    }
    const document = JSON.parse(text) as {
      security: unknown;
      components: { securitySchemes: Record<string, { name: string }> };
    };
    assert.deepEqual(document.security, [{ access: [] }]);
    assert.deepEqual(Object.keys(document.components.securitySchemes), [
      'access',
    ]);
    assert.equal(
      document.components.securitySchemes.access!.name,
      'Cf-Access-Jwt-Assertion',
    );
    // Apart from the Origin each write now asks for, an operation reads as
    // it did, and one that names no sign-in still names none.
    const owner = JSON.parse(
      JSON.stringify(describedBy(HOSTED_ORIGIN, 'owner').paths),
    ) as Record<string, Record<string, { parameters?: { name: string }[] }>>;
    const expected = JSON.parse(
      JSON.stringify(OPENAPI.paths).replace(/"clerk":/g, '"owner":'),
    ) as typeof owner;
    for (const [path, item] of Object.entries(owner)) {
      for (const [method, operation] of Object.entries(item)) {
        const before = expected[path]![method]!.parameters;
        if (operation.parameters && before) {
          operation.parameters = operation.parameters.slice(0, before.length);
        }
      }
    }
    assert.deepEqual(owner, expected);
  });

  it('asks every secured write for the Origin owner and Access sign-in check', () => {
    // principal.ts refuses an owner or Access write with no Origin naming
    // this deployment; Clerk sign-in does not check it.
    for (const mode of ['owner', 'access'] as const) {
      const document = describedBy('https://builder.example.com', mode);
      const missing: string[] = [];
      let writes = 0;
      for (const [path, item] of Object.entries(
        document.paths as Record<string, Record<string, unknown>>,
      )) {
        for (const method of ['post', 'put', 'patch', 'delete']) {
          const operation = item[method] as
            | {
                security?: Record<string, unknown>[];
                parameters?: { name: string; in: string; required?: boolean }[];
              }
            | undefined;
          if (!operation?.security?.some((req) => mode in req)) continue;
          writes += 1;
          const origin = operation.parameters?.find(
            (p) => p.in === 'header' && p.name === 'Origin',
          );
          if (!origin?.required) missing.push(`${method} ${path}`);
        }
      }
      assert.ok(writes > 10, mode);
      assert.deepEqual(missing, [], mode);
    }
    const clerk = describedBy(HOSTED_ORIGIN, 'clerk');
    assert.doesNotMatch(
      JSON.stringify(clerk.paths['/api/projects']),
      /"Origin"/,
    );
  });

  it('says so when the deployment has no sign-in configured', async () => {
    const response = handleOpenApi(
      new Request('https://builder.example.com/api/openapi.json'),
      { VIBLD_AUTH: 'owner' },
    );
    const document = (await response.json()) as typeof OPENAPI;
    assert.match(document.info.description, /^This deployment has no sign-in/);
    assert.match(document.info.description, /not-configured/);
  });

  it('answer a health check without touching anything', async () => {
    const response = handleHealth(
      new Request('https://app.vibld.com/api/health'),
    );
    assert.equal(response.status, 200);
    assert.equal(response.headers.get('cache-control'), 'no-store');
    assert.deepEqual(await response.json(), { status: 'ok' });
  });

  it('answer HEAD with no body, and refuse a write', async () => {
    const head = handleHealth(
      new Request('https://app.vibld.com/api/health', { method: 'HEAD' }),
    );
    assert.equal(head.status, 200);
    assert.equal(await head.text(), '');
    const post = handleOpenApi(
      new Request('https://app.vibld.com/api/openapi.json', { method: 'POST' }),
    );
    assert.equal(post.status, 405);
    assert.equal(post.headers.get('allow'), 'GET, HEAD');
  });
});

/**
 * The two routes that describe this API rather than being part of it
 * (D186): `/api/openapi.json`, the OpenAPI 3.1 document for every public
 * route, and `/api/health`, a liveness check. vibld.com's API catalog
 * (apps/marketing/worker/agent-discovery.ts) points at both.
 *
 * Neither identifies anybody or reads anything stored, so both are open to
 * any origin: an agent reading the description from another site is the
 * point of publishing it.
 */

import { OPENAPI } from './openapi.ts';
import type { PrincipalEnv } from './principal.ts';
import { signInMode, type SignInMode } from './sign-in-mode.ts';

const OPEN = {
  'access-control-allow-origin': '*',
} as const;

function readOnly(request: Request): Response | null {
  if (request.method === 'GET' || request.method === 'HEAD') return null;
  return new Response(JSON.stringify({ error: 'Method not allowed.' }), {
    status: 405,
    headers: {
      ...OPEN,
      allow: 'GET, HEAD',
      'content-type': 'application/json; charset=utf-8',
    },
  });
}

function body(request: Request, text: string): string | null {
  return request.method === 'HEAD' ? null : text;
}

const HOSTED = 'https://app.vibld.com';

/**
 * How a deployment signed in with something other than Clerk is called.
 * The owner's session is the cookie POST /api/auth/owner sets; Access puts
 * its token in a header on every request it lets through.
 */
const SCHEMES = {
  owner: {
    type: 'apiKey',
    in: 'cookie',
    name: 'vibld_owner',
    description:
      'The owner session this deployment sets after `createOwnerSession` (VIBLD_AUTH=owner).',
  },
  access: {
    type: 'apiKey',
    in: 'header',
    name: 'Cf-Access-Jwt-Assertion',
    description:
      'The token Cloudflare Access attaches to a request it lets through (VIBLD_AUTH=access). Its `CF_Authorization` cookie is accepted too.',
  },
} as const;

/** Every `{ clerk: [] }` requirement in `value`, named `scheme` instead. */
function signedInWith(value: unknown, scheme: string): unknown {
  if (Array.isArray(value)) return value.map((v) => signedInWith(v, scheme));
  if (value === null || typeof value !== 'object') return value;
  const entries = Object.entries(value);
  if (entries.length === 1 && entries[0]![0] === 'clerk') {
    return { [scheme]: entries[0]![1] };
  }
  return Object.fromEntries(
    entries.map(([key, v]) => [
      key,
      key === 'securitySchemes' ? v : signedInWith(v, scheme),
    ]),
  );
}

const NOT_CONFIGURED =
  'This deployment has no sign-in configured, so every operation that names a security requirement answers 403 with `reason: "not-configured"` whatever it is sent. ';

/**
 * Owner and Access sign-in refuse a write with no `Origin` naming this
 * deployment (principal.ts, `sameOrigin`), so each secured write asks for
 * one. Clerk sign-in does not check it.
 */
const ORIGIN = {
  name: 'Origin',
  in: 'header',
  required: true,
  description:
    "This deployment's own origin. A write without it is refused 403 under owner or Access sign-in.",
  schema: { type: 'string', format: 'uri' },
} as const;

const WRITES = ['post', 'put', 'patch', 'delete'];

function withOrigin(document: unknown, scheme: string): unknown {
  const doc = document as {
    paths: Record<string, Record<string, Record<string, unknown>>>;
  };
  const paths = Object.fromEntries(
    Object.entries(doc.paths).map(([path, item]) => [
      path,
      Object.fromEntries(
        Object.entries(item).map(([method, operation]) => {
          const security = operation.security as
            Record<string, unknown>[] | undefined;
          const parameters = (operation.parameters ?? []) as {
            name?: string;
            in?: string;
          }[];
          const secured = security?.some((req) => scheme in req) ?? false;
          const named = parameters.some(
            (p) => p.in === 'header' && p.name === 'Origin',
          );
          if (!WRITES.includes(method) || !secured || named) {
            return [method, operation];
          }
          return [
            method,
            { ...operation, parameters: [...parameters, ORIGIN] },
          ];
        }),
      ),
    ]),
  );
  return { ...doc, paths };
}

/**
 * The document as the deployment that served it answers: itself as
 * the server, so a client generated from a self-hosted or preview copy
 * calls that copy, and the sign-in that copy accepts in place of Clerk's.
 * A deployment with no sign-in configured says so rather than offering one
 * it cannot verify.
 */
export function describedBy(
  origin: string,
  mode: SignInMode | undefined,
): typeof OPENAPI {
  const served = {
    ...OPENAPI,
    // Elsewhere the server is `/`, which a client resolves against the URL it
    // fetched this document from. The origin the Worker sees can be `http:`
    // behind a proxy that terminated TLS (infrastructure/vps), and a client
    // told so would send its credentials in the clear.
    servers: [
      origin === HOSTED
        ? { url: HOSTED, description: 'The hosted builder' }
        : { url: '/', description: 'This deployment' },
    ],
  };
  if (mode === undefined) {
    return {
      ...served,
      info: {
        ...served.info,
        description: NOT_CONFIGURED + served.info.description,
      },
    } as typeof OPENAPI;
  }
  if (mode === 'clerk') return served;
  const swapped = withOrigin(
    signedInWith(served, mode),
    mode,
  ) as typeof OPENAPI;
  return {
    ...swapped,
    components: {
      ...swapped.components,
      securitySchemes: { [mode]: SCHEMES[mode] },
    },
  } as unknown as typeof OPENAPI;
}

/** The OpenAPI document, as `application/vnd.oai.openapi+json`. */
export function handleOpenApi(
  request: Request,
  env: PrincipalEnv = {},
): Response {
  const refused = readOnly(request);
  if (refused) return refused;
  const document = describedBy(new URL(request.url).origin, signInMode(env));
  return new Response(body(request, JSON.stringify(document)), {
    headers: {
      ...OPEN,
      'content-type': 'application/vnd.oai.openapi+json; charset=utf-8',
      'cache-control': 'public, max-age=300',
    },
  });
}

/**
 * Whether this Worker is answering: `{ "status": "ok" }`. A liveness check
 * only. It touches no binding, so it stays up when a dependency is down,
 * and says nothing about one.
 */
export function handleHealth(request: Request): Response {
  const refused = readOnly(request);
  if (refused) return refused;
  return new Response(body(request, JSON.stringify({ status: 'ok' })), {
    headers: {
      ...OPEN,
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
    },
  });
}

/**
 * The address a request came from, for the limits keyed on it: the owner's
 * sign-in throttle and the pre-auth limiter read `CF-Connecting-IP`.
 *
 * On Cloudflare the edge sets that header and a client cannot. Under
 * `wrangler dev` behind a server's proxy (D141) it is neither: every request
 * arrives from the proxy on 127.0.0.1, so all clients would share one
 * bucket, and a client-sent `CF-Connecting-IP` is passed through as it came,
 * so anyone could pick their own. There the proxy names the client in a
 * header of its own, which it sets from the connection and never takes from
 * the client (Traefik's `X-Real-Ip`), and `VIBLD_CLIENT_IP_HEADER` names
 * that header. Unset, the request is left exactly as it is.
 */
export interface ClientAddressEnv {
  VIBLD_CLIENT_IP_HEADER?: string;
}

export function withClientAddress(
  request: Request,
  env: ClientAddressEnv,
): Request {
  const header = env.VIBLD_CLIENT_IP_HEADER?.trim();
  if (!header) return request;
  const address = request.headers.get(header)?.split(',')[0]?.trim();
  const headers = new Headers(request.headers);
  // No address from the proxy is one shared, unspoofable bucket, never the
  // client's own choice.
  headers.set('CF-Connecting-IP', address || 'unknown');
  return new Request(request, { headers });
}

